<template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">SERVICE REGISTRY</p><h2>서비스 레지스트리</h2><p>Endpoint·Instance·Health·Routing·Circuit 상태를 운영 가능한 형태로 조회합니다.</p></div><button class="ghost" @click="loadServiceRegistry"><CpfIcon name="refresh"/> 새로고침</button></div><div class="cpf-toolbar"><input v-model="serviceRegistrySearch.serviceId" placeholder="Service ID"><input v-model="serviceRegistrySearch.endpointCode" placeholder="Endpoint"><select v-model="serviceRegistrySearch.instanceStatus"><option value="">전체 상태</option><option>UP</option><option>DOWN</option><option>DRAINING</option><option>DISABLED</option></select><button class="primary" @click="loadServiceRegistry"><CpfIcon name="search"/> 조회</button></div><section class="cpf-kpi-grid"><div class="cpf-stat-card"><span class="label">Services</span><strong class="value">{{serviceRegistryResult.services?.length||0}}</strong></div><div class="cpf-stat-card"><span class="label">Endpoints</span><strong class="value">{{serviceRegistryResult.endpoints?.length||0}}</strong></div><div class="cpf-stat-card"><span class="label">Instances</span><strong class="value">{{serviceRegistryResult.instances?.length||0}}</strong></div><div class="cpf-stat-card"><span class="label">Circuit Open</span><strong class="value">{{openCircuits}}</strong></div></section><div class="cpf-grid-2"><section class="cpf-card"><div class="cpf-card-head"><h2>Instances / Health</h2></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Endpoint</th><th>Instance</th><th>Status</th><th>Weight</th></tr></thead><tbody><tr v-for="r in serviceRegistryResult.instances||[]" :key="String(r.instanceId)"><td>{{r.serviceId}}</td><td>{{r.endpointCode}}</td><td>{{r.instanceName||r.instanceId}}</td><td><span class="cpf-status" :class="r.instanceStatus==='UP'?'success':'danger'">{{r.instanceStatus}}</span></td><td>{{r.weight}}</td></tr></tbody></table></div></section><section class="cpf-card"><div class="cpf-card-head"><h2>Routing / Circuit</h2></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Endpoint</th><th>Policy / State</th><th>Active</th></tr></thead><tbody><tr v-for="r in serviceRegistryResult.routingPolicies||[]" :key="String(r.policyId||r.serviceId+r.endpointCode)"><td>{{r.serviceId}}</td><td>{{r.endpointCode}}</td><td>{{r.policyType||r.routingStrategy||r.policyId}}</td><td>{{r.activeYn}}</td></tr><tr v-for="r in serviceRegistryResult.circuits||[]" :key="'c'+String(r.serviceId)+String(r.endpointCode)+String(r.instanceId)"><td>{{r.serviceId}}</td><td>{{r.endpointCode}}</td><td><span class="cpf-status" :class="r.circuitState==='OPEN'?'danger':'success'">{{r.circuitState}}</span></td><td>{{r.failureCount??0}} failures</td></tr></tbody></table></div></section></div></div></template>
<script lang="ts">import{defineComponent}from"vue";import{admConsoleMixin}from"../../app/admConsoleMixin";import CpfIcon from"../../components/CpfIcon.vue";export default defineComponent({name:"ServiceRegistryPage",components:{CpfIcon},mixins:[admConsoleMixin],computed:{openCircuits(){return(this.serviceRegistryResult?.circuits||[]).filter((r:any)=>String(r.circuitState).toUpperCase()==='OPEN').length}}});</script>
